mapper.sql:
WHERE r.use_yn='Y'
AND (position(lower(#{q}) in lower(r.cand_nm))>0 OR position(lower(#{q}) in lower(r.cand_no))>0)
AND r.job_cd=#{job}
AND r.grd_cd=#{grade}
AND EXISTS(SELECT 1 FROM hr.cand_skl s WHERE s.cand_id=r.cand_id AND s.skl_cd=#{skill})
AND r.cand_se_cd=#{cand_se_cd}
AND r.vndr_ptnr_id=#{vndr_ptnr_id}
AND r.cntct_stts_cd=#{cntct_stts_cd}
AND r.avail_dt <= #{avail_dt}
AND r.avail_dt <= #{shortageEnd} AND r.cntct_stts_cd IN ('NONE','DONE','INTV')
AND coalesce(r.last_cntct_dt,r.created_at::date) < #{cutoff}
